from sqlalchemy import Boolean, Column, Integer, String, Float, DateTime, JSON, Index
from app.core.database import Base
from app.models.base import utc_now


class Signal(Base):
    """Trading signal generated by the deterministic strategy engine."""
    __tablename__ = "signals"

    id = Column(Integer, primary_key=True, autoincrement=True, index=True)
    symbol = Column(String(20), nullable=False, index=True)
    timeframe = Column(String(10), nullable=False, index=True)
    direction = Column(String(10), nullable=False)  # "BUY", "SELL", "WAIT"
    setup_score = Column(Float, nullable=False)
    entry_price = Column(Float, nullable=True)
    stop_loss = Column(Float, nullable=True)
    take_profit_1 = Column(Float, nullable=True)
    take_profit_2 = Column(Float, nullable=True)
    risk_reward = Column(Float, nullable=True)
    fingerprint = Column(String(128), unique=True, nullable=False, index=True)
    reasons = Column(JSON, nullable=False)
    status = Column(String(20), default="ACTIVE", nullable=False)  # "ACTIVE", "INVALIDATED", "TP1_HIT", "TP2_HIT", "SL_HIT", "EXPIRED"
    trend_alignment = Column(String(50), nullable=True)  # "TREND FOLLOWING", "COUNTER-TREND SCALP"
    htf_trend = Column(String(20), nullable=True)  # "BULLISH", "BEARISH", "RANGING"
    is_broadcasted = Column(Boolean, default=False, nullable=False)
    timestamp = Column(DateTime(timezone=True), nullable=False, index=True)
    created_at = Column(DateTime(timezone=True), default=utc_now, nullable=False)

    __table_args__ = (
        Index("ix_signal_symbol_status", "symbol", "status", "timestamp"),
    )
